const m = $json;
const sender = String((m.from && m.from.value && m.from.value[0] && m.from.value[0].address) || '').toLowerCase().trim();
const allowed = String(m.allowed_senders || '').toLowerCase().split(/[,;\s]+/).filter(Boolean);
const authBlob = JSON.stringify(m.headers || {}).toLowerCase();
const senderVerified = /dmarc=pass/.test(authBlob) || (/spf=pass/.test(authBlob) && /dkim=pass/.test(authBlob));

// Strip quoted history from replies
const lines = String(m.text || '').replace(/\r/g, '').split('\n');
const kept = [];
for (const line of lines) {
  if (/^\s*>/.test(line)) break;
  if (/^On .+wrote:\s*$/.test(line.trim())) break;
  if (/^-{2,}\s*Original Message/i.test(line.trim())) break;
  kept.push(line);
}
const body = kept.join('\n').trim();
const subject = String(m.subject || '').replace(/^(re|fwd?):\s*/gi, '').trim();
const firstLine = (body.split('\n')[0] || '').trim();

let request = null;
const cmd = (firstLine + ' ' + subject).match(/\b(APPROVE|REJECT|EVALUATE|CLOSE)\s+(TL-[A-Z0-9-]+)(\s+EARLY)?/i);
if (cmd) {
  const verb = cmd[1].toUpperCase();
  const id = cmd[2].toUpperCase();
  if (verb === 'APPROVE') request = { action: 'approve_trade', experiment_id: id, confirm: true };
  if (verb === 'REJECT') request = { action: 'reject', experiment_id: id };
  if (verb === 'EVALUATE') request = { action: 'evaluate', experiment_id: id };
  if (verb === 'CLOSE') request = { action: 'close_position', experiment_id: id, confirm: true, early_exit: !!cmd[3] };
} else if (body.length >= 10) {
  const amt = body.match(/\$\s?([0-9][0-9,]*)/);
  request = { action: 'analyze', thesis: body.slice(0, 4000), notional_usd: amt ? Number(amt[1].replace(/,/g, '')) : 0 };
}

const isTrade = !!request && (request.action === 'approve_trade' || request.action === 'close_position');
const reasons = [];
if (!sender || !allowed.includes(sender)) reasons.push('sender_not_allowed');
if (isTrade && !senderVerified) reasons.push('sender_not_verified');

return { json: {
  message_id: m.id,
  sender,
  authorized: reasons.length === 0 && !!request,
  allowed_sender: !reasons.includes('sender_not_allowed'),
  reasons,
  has_command: !!request,
  request: request || {},
  api_url: m.api_url,
} };

const r = $json || {};
const req = $('Parse Email Command').item.json.request || {};
const L = [];
const p = r.proposal || {};
if (!r || Object.keys(r).length === 0 || (r.ok === undefined && !r.action)) {
  L.push('ThesisLab could not process this request right now. Nothing was traded. Please try again later.');
} else if (r.action === 'analyze') {
  if ((r.status === 'proposed' || r.status === 'proposal') && r.experiment_id) {
    L.push('Arthur Voss here. Here is the experiment I would run.', '');
    L.push('Experiment: ' + r.experiment_id);
    L.push('Asset vs benchmark: ' + (p.asset || '?') + ' vs ' + (p.benchmark || '?'));
    L.push('Horizon: ' + (p.horizon_days || '?') + ' trading days');
    const risks = Array.isArray(p.risk_warnings) ? p.risk_warnings : [];
    if (p.plain_idea) L.push('', 'The Idea: ' + p.plain_idea);
    L.push('', 'The Bet: ' + (p.falsifiable_claim || ''), '  Measured by close-to-close total return.');
    if (p.reason || p.rationale) L.push('', 'The Reason: ' + (p.reason || p.rationale));
    if (p.main_risk || risks.length) L.push('', 'The Risk: ' + (p.main_risk || risks.join('; ')));
    if (p.invalidation_rule) L.push('', 'What Would Prove Us Wrong: ' + p.invalidation_rule);
    L.push('', 'The Verdict: pending until the test runs.');
    if (p.entry_rule || p.exit_rule) L.push('', 'How we would trade it:');
    if (p.entry_rule) L.push('  Get in: ' + p.entry_rule);
    if (p.exit_rule) L.push('  Get out: ' + p.exit_rule);
    if (p.market_data_summary) L.push('', 'Market data: ' + p.market_data_summary);
    if (p.main_risk && risks.length) L.push('Other risks: ' + risks.join('; '));
    L.push('', 'Paper allocation: $' + r.notional_usd + (r.allocation_capped ? ' (capped by ThesisLab policy)' : ''));
    L.push('', 'Nothing has been traded. To place this PAPER order, reply with exactly:', '  APPROVE ' + r.experiment_id, 'To discard it, reply:', '  REJECT ' + r.experiment_id);
  } else {
    L.push('Arthur Voss here. I could not turn this into a tradable experiment yet.');
    if (p.clarification_question) L.push('', 'Question: ' + p.clarification_question);
    if (Array.isArray(r.validation_errors) && r.validation_errors.length) L.push('', 'Issues: ' + r.validation_errors.join('; '));
    L.push('', 'No order can be placed for this result. Reply with a revised thesis to try again.');
  }
} else if (r.action === 'approve_trade') {
  if (r.ok) L.push('Paper order submitted for ' + r.experiment_id + '.', 'Order: ' + r.paper_order_id + ' (' + r.order_status + '), ' + r.symbol + ', $' + r.notional_usd + ' notional.', 'Alpaca PAPER trading only. If the market is closed it fills at the next session.', '', 'Later, reply EVALUATE ' + r.experiment_id + ' to score it, or CLOSE ' + r.experiment_id + ' to exit after the horizon.');
  else L.push('Approval for ' + (r.experiment_id || req.experiment_id) + ' was blocked. No order was placed.', 'Reasons: ' + ((r.reasons || []).join('; ') || r.error || 'unknown'));
} else if (r.action === 'reject') {
  L.push(r.ok ? 'Experiment ' + r.experiment_id + ' rejected. No order was placed.' : 'Could not reject ' + (r.experiment_id || req.experiment_id) + ': it was not found or is no longer pending.');
} else if (r.action === 'evaluate') {
  if (r.ok && r.outcome) {
    const o = r.outcome;
const VL = (v) => { const s = String(v || ''); const base = s.replace(/^interim_/, ''); const m = { supported: 'Held up', rejected: "Didn't hold up", inconclusive: 'Too close to call' }; return (s.indexOf('interim_') === 0 ? 'Early read: ' : '') + (m[base] || s); };
    L.push('Results for ' + r.experiment_id + ':', '');
    L.push('The Verdict: ' + (o.verdict_label || VL(o.verdict)));
    L.push('Our pick: ' + o.asset_return + ' | Benchmark: ' + o.benchmark_return + ' | Difference: ' + o.alpha);
    L.push('Progress: ' + o.trading_days_elapsed + ' of ' + o.horizon_days + ' trading days' + (o.horizon_complete ? ' (test complete)' : ''));
    L.push('Entry price: $' + o.fill_price + ', latest close: $' + o.asset_last_close + ' (as of ' + String(o.as_of || '').slice(0, 10) + ')');
    L.push('', 'Positions are not closed by evaluation. Reply CLOSE ' + r.experiment_id + ' after the horizon, or CLOSE ' + r.experiment_id + ' EARLY to exit now.');
  } else L.push('Could not evaluate ' + (r.experiment_id || req.experiment_id) + ': ' + (r.error || 'unknown error') + '.');
} else if (r.action === 'close_position') {
  if (r.ok) L.push('Paper position closed for ' + r.experiment_id + (r.early_exit ? ' (early exit)' : '') + '.', 'Sell order: ' + r.sell_order_id + ' (' + r.sell_order_status + '), ' + r.qty + ' ' + r.symbol + '.', 'Alpaca PAPER trading only.');
  else L.push('Close for ' + (r.experiment_id || req.experiment_id) + ' was blocked. Nothing was sold.', 'Reasons: ' + ((r.reasons || []).join('; ') || r.error || 'unknown'));
} else {
  L.push('ThesisLab returned an unexpected response. Nothing was traded.');
}
L.push('', '--', 'ThesisLab (paper trading only). Commands: send a thesis in plain English, or reply APPROVE / REJECT / EVALUATE / CLOSE <experiment id>.');
return { json: { message_id: $('Parse Email Command').item.json.message_id, reply_text: L.join('\n') } };
